11	// capProtectScene 是“满池中等待投票与排队交易混合存在”的固定场景：
12	//
13	//	keys[0] lp     费用 10：仅被本地提议引用（本地提议独有）
14	//	keys[1] cp     费用 20：仅被竞争候选引用（其他已登记候选独有）
15	//	keys[2] shared 费用 30：同时被本地提议与竞争候选引用（多候选共享）
16	//	keys[3] q1..q3 费用 50/60/70：始终排队，q1 是唯一可被淘汰的最低费交易
17	//	keys[4]：提交新交易使用的“其他发送者”
18	//
19	// 容量为 6，场景建成后池恰好满：三笔受保护交易占三个位置，三笔排队交易占三个
20	// 位置。竞争候选已取得一票，本地提议、候选顺序、区块标识与票数在场景内冻结。
21	type capProtectScene struct {
22		n      *Node
23		keys   []testKey
24		lp     *Transaction
25		cp     *Transaction
26		shared *Transaction
27		q1     *Transaction
28		q2     *Transaction
29		q3     *Transaction
30		local  ProposalView
31		altID  string
32	}
33	
34	func newCapProtectScene(t *testing.T) *capProtectScene {
35		t.Helper()
36		keys := genKeys(t, 5)
37		vals := make([][]byte, len(keys))
38		for i, k := range keys {
39			vals[i] = k.pub
40		}
41		n, err := New(t.TempDir(), Config{
42			Seed: []byte("cap-protect-scene"), Validators: vals,
43			MaxTxsPerBlock: 2, PoolCapacity: 6,
44		})
45		if err != nil {
46			t.Fatal(err)
47		}
48	
49		s := &capProtectScene{n: n, keys: keys}
50		// 先只放入会进入本地提议的两笔，冻结提议；其余交易在提议之后提交。
51		s.lp = NewTransaction(keys[0].priv, 1, []byte("local-only"), 10, 100)
52		s.shared = NewTransaction(keys[2].priv, 1, []byte("shared"), 30, 100)
53		for _, tx := range []*Transaction{s.lp, s.shared} {
54			if _, err := n.Submit(tx); err != nil {
55				t.Fatal(err)
56			}
57		}
58		local, err := n.Propose()
59		if err != nil {
60			t.Fatal(err)
61		}
62		// 费用高的 shared 在前，lp 在后：本地提议顺序固定。
63		if !reflect.DeepEqual(local.TxIDs, []string{s.shared.ID(), s.lp.ID()}) {
64			t.Fatalf("local proposal = %v, want [shared lp]", local.TxIDs)
65		}
66		s.local = local
67	
68		// 提议冻结后新交易不再进入本地提议：三笔排队交易与竞争候选独有交易入池。
69		s.q1 = NewTransaction(keys[3].priv, 1, []byte("q1"), 50, 100)
70		s.q2 = NewTransaction(keys[3].priv, 2, []byte("q2"), 60, 100)
71		s.q3 = NewTransaction(keys[3].priv, 3, []byte("q3"), 70, 100)
72		s.cp = NewTransaction(keys[1].priv, 1, []byte("candidate-only"), 20, 100)
73		for _, tx := range []*Transaction{s.q1, s.q2, s.q3, s.cp} {
74			if _, err := n.Submit(tx); err != nil {
75				t.Fatal(err)
76			}
77		}
78	
79		// 竞争候选同时引用 shared（已在本地提议中）与 cp（排队）：
80		// 登记后 cp 转为等待投票，shared 被两个候选共同引用仍只占一个位置。
81		s.altID = registerMust(t, n, 1, []string{s.shared.ID(), s.cp.ID()})
82		if s.altID == s.local.BlockID {
83			t.Fatal("competing candidate must have a distinct block id")
84		}
85	
86		// 竞争候选先取得一票，后续提交不得改动已取得的票。
87		vres, err := n.Vote(keys[0].pub, 1, s.altID)
88		if err != nil || !vres.Counted {
89			t.Fatalf("vote for competing candidate: %+v %v", vres, err)
90		}
91	
92		s.assertMixedShape(t)
93		return s
94	}
95	
96	// assertMixedShape 固定场景建成时的混合形态：受保护交易等待投票，
97	// q1..q3 等待打包，池计数恰为容量 6，两个候选均 pending。
98	func (s *capProtectScene) assertMixedShape(t *testing.T) {
99		t.Helper()
100		n := s.n
101		if got := n.st.poolSize(); got != 6 {
102			t.Fatalf("pool size = %d, want 6 (full)", got)
103		}
104		for _, tx := range []*Transaction{s.lp, s.cp, s.shared} {
105			if info, _ := n.Tx(tx.ID()); info.Status != StatusProposed {
106				t.Fatalf("protected tx %s status = %s, want proposed", tx.ID(), info.Status)
107			}
108		}
109		for _, tx := range []*Transaction{s.q1, s.q2, s.q3} {
110			if info, _ := n.Tx(tx.ID()); info.Status != StatusQueued {
111				t.Fatalf("queued tx %s status = %s, want queued", tx.ID(), info.Status)
112			}
113		}
114		// 账户视角：受保护交易等待投票，排队交易等待打包。
115		assertAccountQueue(t, n, s.keys[0].pub, 0, map[string]string{s.lp.ID(): "waiting-vote"})
116		assertAccountQueue(t, n, s.keys[1].pub, 0, map[string]string{s.cp.ID(): "waiting-vote"})
117		assertAccountQueue(t, n, s.keys[2].pub, 0, map[string]string{s.shared.ID(): "waiting-vote"})
118		assertAccountQueue(t, n, s.keys[3].pub, 0, map[string]string{
119			s.q1.ID(): "waiting-pack", s.q2.ID(): "waiting-pack", s.q3.ID(): "waiting-pack",
120		})
121		rc := mustCandidates(t, n, 1)
122		if len(rc.Candidates) != 2 || rc.Ended {
123			t.Fatalf("round state = %+v, want two pending candidates", rc)
124		}
125		for _, c := range rc.Candidates {
126			if c.Result != CandidatePending {
127				t.Fatalf("candidate %s result = %s, want pending", c.BlockID, c.Result)
128			}
129		}
130	}
131	
132	// capEntrySnap 记录一笔交易在提交前后的状态与全部关联字段。
133	type capEntrySnap struct {
134		status     TxStatus
135		replacedBy string
136		dropReason string
137		dropRound  uint64
138	}
139	
140	func capEntrySnapshot(n *Node) map[string]capEntrySnap {
141		out := make(map[string]capEntrySnap, len(n.st.Entries))
142		for id, e := range n.st.Entries {
143			out[id] = capEntrySnap{
144				status:     TxStatus(e.Status),
145				replacedBy: e.ReplacedBy,
146				dropReason: e.DropReason,
147				dropRound:  e.DropRound,
148			}
149		}
150		return out
151	}
152	
153	// capAccountSnap 记录全部相关账户的已确认序号、缺口与待处理（标识+等待说明）序列。
154	func capAccountSnap(n *Node, keys []testKey) map[string]string {
155		out := make(map[string]string, len(keys))
156		for _, k := range keys {
157			acct := n.Account(k.pub)
158			parts := make([]string, 0, len(acct.Pending))
159			for _, p := range acct.Pending {
160				parts = append(parts, p.ID+":"+p.Note)
161			}
162			out[acct.Sender] = joinSnap(acct.ConfirmedSequence, acct.Gap, parts)
163		}
164		return out
165	}
166	
167	func joinSnap(confirmed, gap uint64, pending []string) string {
168		return "confirmed=" + strconv.FormatUint(confirmed, 10) + "|gap=" + strconv.FormatUint(gap, 10) + "|pending=" + strings.Join(pending, ",")
169	}
170	
171	// assertFrozenViews 断言本地提议、候选（交易顺序、区块标识、票数、结果）、
172	// 全部历史条目状态与账户待处理列表与提交前快照完全一致；没有新确认块。
173	func (s *capProtectScene) assertFrozenViews(t *testing.T,
174		beforeEntries map[string]capEntrySnap, beforeAccounts map[string]string,
175		beforeLocal ProposalView, beforeRC *RoundCandidates,
176	) {
177		t.Helper()
178		n := s.n
179		if got, ok := n.Proposal(); !ok || !reflect.DeepEqual(got, beforeLocal) {
180			t.Fatalf("local proposal changed:\nbefore=%+v\nafter =%+v ok=%v", beforeLocal, got, ok)
181		}
182		if rc := mustCandidates(t, n, 1); !reflect.DeepEqual(rc, beforeRC) {
183			t.Fatalf("candidates view changed:\nbefore=%+v\nafter =%+v", beforeRC, rc)
184		}
185		if got := capEntrySnapshot(n); !reflect.DeepEqual(got, beforeEntries) {
186			t.Fatalf("tx entries changed by rejected submit:\nbefore=%v\nafter =%v", beforeEntries, got)
187		}
188		if got := capAccountSnap(n, s.keys); !reflect.DeepEqual(got, beforeAccounts) {
189			t.Fatalf("accounts changed by rejected submit:\nbefore=%v\nafter =%v", beforeAccounts, got)
190		}
191		if n.Height() != 0 {
192			t.Fatalf("height = %d, rejection must not confirm anything", n.Height())
193		}
194		if _, ok := n.LatestBlock(); ok {
195			t.Fatal("rejection must not leave a confirmed block")
196		}
197	}
198	
199	func (s *capProtectScene) snapshots(t *testing.T) (map[string]capEntrySnap, map[string]string, ProposalView, *RoundCandidates) {
200		t.Helper()
201		prop, ok := s.n.Proposal()
202		if !ok {
203			t.Fatal("local proposal missing")
204		}
205		return capEntrySnapshot(s.n), capAccountSnap(s.n, s.keys), prop, mustCandidates(t, s.n, 1)
206	}
207	
208	// 成功路径：新交易费用高于唯一可淘汰的 q1 时，挤出 q1 且只涉及 q1。
209	// 受保护交易即使费用最低（lp 费用 10）也保留；被挤出的是可淘汰交易中费用最低者。
210	func TestCapacityMixedProtectionEvictsOnlyQueued(t *testing.T) {
211		s := newCapProtectScene(t)
212		n := s.n
213		beforeEntries, beforeAccounts, beforeLocal, beforeRC := s.snapshots(t)
214	
215		win := NewTransaction(s.keys[4].priv, 1, []byte("winner"), 51, 100) // 高于 q1(50)，低于 q2/q3
216		res, err := n.Submit(win)
217		if err != nil {
218			t.Fatalf("higher-fee tx must displace the lowest queued tx: %v", err)
219		}
220		if res.TxID != win.ID() || res.EvictedID != s.q1.ID() || res.ReplacedID != "" {
221			t.Fatalf("submit result = %+v, want accept with evicted q1 and no replace link", res)
222		}
223	
224		// 被挤出的 q1：dropped / pool-capacity / 发生轮次 1，原内容保留，无确认块与替换关联。
225		info, err := n.Tx(s.q1.ID())
226		if err != nil {
227			t.Fatal(err)
228		}
229		if info.Status != StatusDropped || info.DropReason != DropReasonPoolCapacity || info.DropRound != 1 {
230			t.Fatalf("q1 after eviction = %+v, want dropped/pool-capacity/round 1", info)
231		}
232		if info.BlockHeight != 0 || info.BlockID != "" || info.ReplacedBy != "" {
233			t.Fatalf("dropped q1 must not carry block/replace links: %+v", info)
234		}
235		assertTxMatches(t, info.Tx, s.q1)
236	
237		// q1 从账户待处理列表退出，已确认序号不推进；q2、q3 保留且留下序号 1 的缺口。
238		acct3 := n.Account(s.keys[3].pub)
239		if acct3.ConfirmedSequence != 0 || acct3.Gap != 1 || len(acct3.Pending) != 2 {
240			t.Fatalf("q1 sender account = %+v, want confirmed 0 gap 1 two pending", acct3)
241		}
242		if acct3.Pending[0].ID != s.q2.ID() || acct3.Pending[1].ID != s.q3.ID() {
243			t.Fatalf("remaining pending = [%s %s], want [q2 q3]", acct3.Pending[0].ID, acct3.Pending[1].ID)
244		}
245	
246		// 新交易排队等待打包，提交结果不带替换关联。
247		winInfo, err := n.Tx(win.ID())
248		if err != nil || winInfo.Status != StatusQueued {
249			t.Fatalf("new tx = %+v %v, want queued", winInfo, err)
250		}
251		assertAccountQueue(t, n, s.keys[4].pub, 0, map[string]string{win.ID(): "waiting-pack"})
252	
253		// 其余交易与受保护交易状态、关联记录一律不变。
254		for id, before := range beforeEntries {
255			if id == s.q1.ID() {
256				continue
257			}
258			after, ok := n.st.Entries[id]
259			if !ok {
260				t.Fatalf("tx %s vanished", id)
261			}
262			got := capEntrySnap{
263				status:     TxStatus(after.Status),
264				replacedBy: after.ReplacedBy,
265				dropReason: after.DropReason,
266				dropRound:  after.DropRound,
267			}
268			if got != before {
269				t.Fatalf("tx %s changed: before=%+v after=%+v", id, before, got)
270			}
271			// 其余排队交易（q2、q3）内容原样保留。
272			if after.Status == stQueued {
273				if want := lookupSceneTx(s, id); want != nil {
274					assertTxMatches(t, mustTx(t, n, id).Tx, want)
275				}
276			}
277		}
278		// 受保护交易内容原样保留。
279		for _, tx := range []*Transaction{s.lp, s.cp, s.shared, s.q2, s.q3} {
280			assertTxMatches(t, mustTx(t, n, tx.ID()).Tx, tx)
281		}
282		// 受保护账户仍只有等待投票的原交易。
283		assertAccountQueue(t, n, s.keys[0].pub, 0, map[string]string{s.lp.ID(): "waiting-vote"})
284		assertAccountQueue(t, n, s.keys[1].pub, 0, map[string]string{s.cp.ID(): "waiting-vote"})
285		assertAccountQueue(t, n, s.keys[2].pub, 0, map[string]string{s.shared.ID(): "waiting-vote"})
286		assertAccountQueue(t, n, s.keys[3].pub, 0, map[string]string{
287			s.q2.ID(): "waiting-pack", s.q3.ID(): "waiting-pack",
288		})
289		// 三个受保护账户的待处理序列化与提交前完全相同；新交易账户此前为空。
290		// 账户 3 因 q1 被挤出而变化，已在上面单独校验。
291		afterAccounts := capAccountSnap(n, s.keys)
292		for i := 0; i < 3; i++ {
293			k := fmt.Sprintf("%x", s.keys[i].pub)
294			if afterAccounts[k] != beforeAccounts[k] {
295				t.Fatalf("protected account %d changed:\nbefore=%s\nafter =%s", i, beforeAccounts[k], afterAccounts[k])
296			}
297		}
298		if before := beforeAccounts[fmt.Sprintf("%x", s.keys[4].pub)]; before != "confirmed=0|gap=0|pending=" {
299			t.Fatalf("new sender should have been empty before submit, got %s", before)
300		}
301	
302		// 本地提议、竞争候选的交易顺序、区块标识与已取得的票均不受影响。
303		if got, ok := n.Proposal(); !ok || !reflect.DeepEqual(got, beforeLocal) {
304			t.Fatalf("local proposal changed:\nbefore=%+v\nafter =%+v ok=%v", beforeLocal, got, ok)
305		}
306		rc := mustCandidates(t, n, 1)
307		if !reflect.DeepEqual(rc, beforeRC) {
308			t.Fatalf("candidates changed:\nbefore=%+v\nafter =%+v", beforeRC, rc)
309		}
310		local := candidateByBlockID(rc, s.local.BlockID)
311		alt := candidateByBlockID(rc, s.altID)
312		if local == nil || alt == nil || !local.Local {
313			t.Fatalf("candidate set after eviction wrong: local=%v alt=%v", local, alt)
314		}
315		if !reflect.DeepEqual(local.TxIDs, []string{s.shared.ID(), s.lp.ID()}) {
316			t.Fatalf("local order = %v, want [shared lp]", local.TxIDs)
317		}
318		if !reflect.DeepEqual(alt.TxIDs, []string{s.shared.ID(), s.cp.ID()}) {
319			t.Fatalf("competing order = %v, want [shared cp]", alt.TxIDs)
320		}
321		if len(alt.Voters) != 1 {
322			t.Fatalf("competing candidate votes = %d, want 1 preserved", len(alt.Voters))
323		}
324		// 计数守恒：挤一出一，池仍恰好满。
325		if got := n.st.poolSize(); got != 6 {
326			t.Fatalf("pool size after eviction = %d, want 6", got)
327		}
328		if n.Height() != 0 {
329			t.Fatalf("height = %d, eviction must not confirm", n.Height())
330		}
331	}
332	
333	// 同费但标识更小时同样挤出 q1，其余一切与高费成功路径一致。
334	func TestCapacityMixedProtectionSameFeeSmallerID(t *testing.T) {
335		s := newCapProtectScene(t)
336		n := s.n
337	
338		smaller := craftTxWithID(t, s.keys[4].priv, 1, 50, s.q1.ID(), true)
339		if smaller.ID() >= s.q1.ID() {
340			t.Fatal("test setup: crafted id must be smaller than q1")
341		}
342		res, err := n.Submit(smaller)
343		if err != nil {
344			t.Fatalf("same-fee smaller-id tx must evict q1: %v", err)
345		}
346		if res.EvictedID != s.q1.ID() || res.ReplacedID != "" {
347			t.Fatalf("result = %+v, want evicted q1 without replacement", res)
348		}
349		if info, _ := n.Tx(s.q1.ID()); info.Status != StatusDropped || info.DropRound != 1 {
350			t.Fatalf("q1 = %+v, want dropped in round 1", info)
351		}
352		if info, _ := n.Tx(smaller.ID()); info.Status != StatusQueued {
353			t.Fatalf("new tx status = %s, want queued", info.Status)
354		}
355		// 受保护交易即使标识/费用不占优也保持等待投票。
356		for _, tx := range []*Transaction{s.lp, s.cp, s.shared} {
357			if info, _ := n.Tx(tx.ID()); info.Status != StatusProposed {
358				t.Fatalf("protected tx %s = %s, want proposed", tx.ID(), info.Status)
359			}
360		}
361	}
362	
363	// 拒绝路径一：新交易费用高于每一笔受保护交易（lp 10、cp 20、shared 30），
364	// 却低于所有可淘汰交易（q1 50 起步）时，必须 pool-full：不能挤出候选中的低费
365	// 交易，也不能仅因比受保护交易贵就被接收。
366	func TestCapacityMixedProtectionRejectHigherThanProtected(t *testing.T) {
367		s := newCapProtectScene(t)
368		n := s.n
369		beforeEntries, beforeAccounts, beforeLocal, beforeRC := s.snapshots(t)
370	
371		rejected := NewTransaction(s.keys[4].priv, 1, []byte("rejected-40"), 40, 100)
372		res, err := n.Submit(rejected)
373		if reason(err) != ReasonPoolFull {
374			t.Fatalf("submit got %v, want %s", err, ReasonPoolFull)
375		}
376		if res != nil {
377			t.Fatalf("rejected submit returned result %+v, want nil", res)
378		}
379		if _, err := n.Tx(rejected.ID()); reason(err) != ReasonUnknownTx {
380			t.Fatalf("rejected tx query = %v, want %s", err, ReasonUnknownTx)
381		}
382		// q1 仍是排队交易，没有任何淘汰记录。
383		if info, _ := n.Tx(s.q1.ID()); info.Status != StatusQueued || info.DropReason != "" {
384			t.Fatalf("q1 after rejection = %+v, want untouched queued", info)
385		}
386		s.assertFrozenViews(t, beforeEntries, beforeAccounts, beforeLocal, beforeRC)
387	}
388	
389	// 拒绝路径二：与可淘汰对象 q1 同费、但标识更大时，同样 pool-full；
390	// 受保护交易与候选视图保持提交前结果。
391	func TestCapacityMixedProtectionRejectSameFeeLargerID(t *testing.T) {
392		s := newCapProtectScene(t)
393		n := s.n
394		beforeEntries, beforeAccounts, beforeLocal, beforeRC := s.snapshots(t)
395	
396		larger := craftTxWithID(t, s.keys[4].priv, 1, 50, s.q1.ID(), false)
397		if larger.ID() <= s.q1.ID() {
398			t.Fatal("test setup: crafted id must be larger than q1")
399		}
400		res, err := n.Submit(larger)
401		if reason(err) != ReasonPoolFull {
402			t.Fatalf("submit got %v, want %s", err, ReasonPoolFull)
403		}
404		if res != nil {
405			t.Fatalf("rejected submit returned result %+v, want nil", res)
406		}
407		if _, err := n.Tx(larger.ID()); reason(err) != ReasonUnknownTx {
408			t.Fatalf("rejected tx query = %v, want %s", err, ReasonUnknownTx)
409		}
410		s.assertFrozenViews(t, beforeEntries, beforeAccounts, beforeLocal, beforeRC)
411	}
412	
413	func mustTx(t *testing.T, n *Node, id string) *TxInfo {
414		t.Helper()
415		info, err := n.Tx(id)
416		if err != nil {
417			t.Fatal(err)
418		}
419		return info
420	}
421	
422	func lookupSceneTx(s *capProtectScene, id string) *Transaction {
423		for _, tx := range []*Transaction{s.lp, s.cp, s.shared, s.q1, s.q2, s.q3} {
424			if tx.ID() == id {
425				return tx
426			}
427		}
428		return nil
429	}
