472		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
473		n.Submit(a)
474		p, _ := n.Propose()
475		confirmByVotes(t, n, keys, p.BlockID)
476	
477		// 改写为版本 2 并删除容量字段。
