9	// 提议顺序的完整断言辅助：提议的交易标识序列必须与 want 完全一致。
10	func assertProposalOrder(t *testing.T, n *Node, want []string) ProposalView {
11		t.Helper()
12		p, err := n.Propose()
13		if err != nil {
14			t.Fatal(err)
15		}
16		if fmt.Sprint(p.TxIDs) != fmt.Sprint(want) {
17			t.Fatalf("proposal order = %v, want %v", p.TxIDs, want)
18		}
19		return p
20	}
21	
22	// 断言账户的已确认序号与每笔待处理交易的等待说明（waiting-vote / waiting-pack）。
23	func assertAccountQueue(t *testing.T, n *Node, pub ed25519.PublicKey, confirmed uint64, notes map[string]string) {
24		t.Helper()
25		acct := n.Account(pub)
26		if acct.ConfirmedSequence != confirmed {
27			t.Fatalf("confirmed sequence = %d, want %d", acct.ConfirmedSequence, confirmed)
28		}
29		if len(acct.Pending) != len(notes) {
30			t.Fatalf("pending count = %d, want %d (%+v)", len(acct.Pending), len(notes), acct.Pending)
31		}
32		for _, info := range acct.Pending {
33			want, ok := notes[info.ID]
34			if !ok {
35				t.Fatalf("unexpected pending tx %s", info.ID)
36			}
37			if info.Note != want {
38				t.Fatalf("tx %s note = %q, want %q", info.ID, info.Note, want)
39			}
40		}
41	}
