	if res.TxID != newTx.ID() || res.EvictedID != victim.ID() || res.ReplacedID != "" {
		t.Fatalf("submit result = %+v, want TxID=%s EvictedID=%s no replace link",
			res, newTx.ID(), victim.ID())
	}

	// 新交易：queued，完整内容与费用原样保留，账户显示等待打包。
